std::vector<std::uint8_t> read(const fs::path& path){std::ifstream in(path,std::ios::binary);return {std::istreambuf_iterator<char>(in),{}};}
void write(const fs::path& path,std::string_view value){std::ofstream out(path,std::ios::binary|std::ios::trunc);out.write(value.data(),value.size());check(bool(out),"owned synthetic bytes written");}
bool same(const app::FileObjectIdentity& a,const app::FileObjectIdentity& b){return a.volume==b.volume&&a.file_id==b.file_id;}
win::installation::Handle open(const fs::path& path,DWORD access=GENERIC_READ,DWORD sharing=FILE_SHARE_READ){win::installation::Handle h(CreateFileW(path.c_str(),access,sharing,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr));check(h.get()!=INVALID_HANDLE_VALUE,"actual owned native file handle");return h;}
app::FileObjectIdentity raw(HANDLE file){return {std::to_string(win::installation::volume_serial(file)),std::to_string(win::installation::file_id(file))};}
app::FileObjectIdentity logical(const fs::path& path){auto h=open(path);return win::portable_logical_file_identity(path,h.get());}
